-- =====================================================================
-- Milestone Proyek 6 : Proyek Klinik Sehat ZI
--
--
-- PARAMETER = (35 mod 9) + 1 = 9
--   tabel transaksi utama (kunjungan) minimal 10 x P = 90 baris
--   tersebar pada 18 tanggal berbeda (5 kunjungan per hari)
--   batas jenis obat per resep (AB-09) = P + 2 = 11
--
-- ISI (jumlah baris): pasien 5, obat 5, pemasok 5,
--   kunjungan 90, pemeriksaan 90, resep 74,
--   detail_resep 113, pembayaran 90,
--   penerimaan 4, detail_penerimaan 10
--
-- =====================================================================

USE klinik_035;

-- ---------------------------------------------------------------------
-- 1. Data induk
-- ---------------------------------------------------------------------

-- Pasien (AB-01: nomor pasien berbeda; NIK wajib dan unik). Pasien pertama = contoh dokumen sumber p02.

-- Obat. stok_obat diisi stok awal; stok akhir dihitung pada bagian 3 (AB-06: tidak negatif).

-- Pemasok

-- ---------------------------------------------------------------------
-- 2. Data transaksi
-- ---------------------------------------------------------------------

-- Kunjungan (90 baris, 18 tanggal). AB-02: nomor kunjungan berbeda, terhubung dengan satu pasien.

-- Pemeriksaan: satu pemeriksaan per kunjungan (AB-03).

-- Resep (74 baris): hanya kunjungan yang membutuhkan obat (AB-04).

-- Detail resep: setiap resep memuat 1 sampai 2 jenis obat (AB-05; batas AB-09 = 11).

-- Pembayaran: satu pembayaran per kunjungan (AB-07). total_bayar = biaya konsultasi + harga x jumlah obat.

-- Penerimaan obat dari pemasok (id diisi eksplisit karena tabel tidak punya kode alami).


-- ---------------------------------------------------------------------
-- 3. Stok akhir (AB-06: stok tidak boleh negatif)
-- ---------------------------------------------------------------------
-- stok akhir = stok awal + jumlah diterima - jumlah diresepkan.
-- Satu perintah, memakai kolom kunci pada WHERE (aman untuk sql_safe_updates).
-- Bila hasilnya negatif, constraint ck_obat_stok menolak perintah ini.
UPDATE obat
SET stok_obat = stok_obat
  + COALESCE((SELECT SUM(dp.jumlah_diterima) FROM detail_penerimaan dp WHERE dp.id_obat = obat.id_obat), 0)
  - COALESCE((SELECT SUM(dr.jumlah_obat)     FROM detail_resep dr      WHERE dr.id_obat = obat.id_obat), 0)
WHERE id_obat > 0;

-- ---------------------------------------------------------------------
-- 4. Pemeriksaan jumlah baris (hasil yang diharapkan ada di p06_uji_25430035.md)
-- ---------------------------------------------------------------------
SELECT 'pasien' AS tabel, COUNT(*) AS jumlah_baris FROM pasien
UNION ALL SELECT 'obat', COUNT(*) FROM obat
UNION ALL SELECT 'pemasok', COUNT(*) FROM pemasok
UNION ALL SELECT 'kunjungan', COUNT(*) FROM kunjungan
UNION ALL SELECT 'pemeriksaan', COUNT(*) FROM pemeriksaan
UNION ALL SELECT 'resep', COUNT(*) FROM resep
UNION ALL SELECT 'detail_resep', COUNT(*) FROM detail_resep
UNION ALL SELECT 'pembayaran', COUNT(*) FROM pembayaran
UNION ALL SELECT 'penerimaan', COUNT(*) FROM penerimaan
UNION ALL SELECT 'detail_penerimaan', COUNT(*) FROM detail_penerimaan;